// TH18 v1.00a st03bs.ecl.txt:356-462, Boss3 non-spell (BossCard2 -> Boss3).
// Source t0 is Boss3 entry; 120-frame shell buffer precedes it. Boss3 waits 90+80,
// then repeats an attack at +0 and moveRand at +120 after each call.
const TIME_LIMIT: int = 2222;
const SOURCE_LIMIT: int = 2100;
const OPENING_BUFFER: int = 120;
const TH18_SHARD: int = 512; // source type10 (radius 2.4), color 13

// Source Boss3_at 431-452 EX chain:
//   ANIM a1 (sh_dist below), OFFSCREEN 200,
//   VELTIME60 3.2 -> 0.03 along current direction,
//   VELTIME30 0.03 -> 2.0 toward player + E,
//   VELTIME30 2.0 -> 0.03 along current direction,
//   VELTIME30 0.03 -> 2.0 toward player + F + H*RANDF2.
// The WAIT10 in slot3 is overwritten by the E VELTIME before etOn and never runs.
// Same six-record finite chain as Boss2_at, so OFFSCREEN 200 -> 195.
xformdef BOSS3_MOTION(eoff: angle, foff: angle, hbam: int) {
    offscreen_keep(195);
    @60 set_accel((0.03fx-3.2fx)/60fx);
    set_angle(at_effect(aim_player()+eoff));
    set_accel((2.0fx-0.03fx)/30fx);
    wait(30);
    set_accel((0.03fx-2.0fx)/30fx);
    wait(30);
    // Source 451-452 samples RANDF2 at configuration time; at_spawn keeps that
    // per-bullet draw, while the aim direction itself is read at effect entry.
    set_angle(at_effect(aim_player()+foff));
    turn(at_spawn(((rand(65536)-32768)*hbam/32768) as angle));
    set_accel((2.0fx-0.03fx)/30fx);
    wait(30);
    stop_fx();
}

// Source Boss3_at 420-462: B=10 fixed, C=I0 (60/60/60/70).
// Each outer group advances E/F by 2pi/10 and D by (2pi/10)/C before emitting;
// each inner bullet advances G by 2pi/C after etOn.
sub boss3_at(aoff: angle, c: int) {
    var rank: int = global(GVAR_RANK);
    var b: int = 10;
    var hbam: int = 910;             // diffF(H): 5deg rank0
    if rank == 1 { hbam = 2367; }    // 13deg rank1
    if rank >= 2 { hbam = 2731; }    // 15deg rank2/3
    var d0: angle = rand(65536) as angle; // RANDRAD
    var e0: angle = rand(65536) as angle; // RANDRAD
    sh_reset(0);
    sh_sprite(0, TH18_SHARD, 13);
    sh_ring(0, 1);
    sh_aim(0, 0);                    // etAim mode3 fixed-direction ring
    sh_count(0, c, 1);               // C-way fixed ring, one speed layer
    sh_angle(0, 0deg, 0deg);
    sh_speed(0, 3.2fx, 0fx);
    sh_dist(0, -12.8fx);             // ANIM a1: -4 * initial speed 3.2
    for j in 0..b {
        var e: angle = e0+(((j+1)*65536/b) as angle);
        var f: angle = e+aoff;       // source F = E + A
        var d: angle = d0+((((j+1)*65536/b)/c) as angle);
        sh_angle(0, d, 0deg);        // inner G base; ring supplies 2pi/C steps
        sh_xform(0, BOSS3_MOTION(e, f, hbam));
        sh_fire(0);
    }
}

// Source Boss3 367 moveLimit(0,128,280,64): x[-140,140], y[96,160].
// moveRand(60,4,0.7) keeps speed mode0, so speed(k)=0.7*(1-k/60).
// Direction inner tests use x+-70, y112/144 (movement.md).
sub card_arm_next_step() {
    var k: int = self_int(0)+1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = 0.7fx*((60-k) as fx)/60fx; }
    var nx: fx = $self_x+self_fx(0)*speed;
    var ny: fx = $self_y+self_fx(1)*speed;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx-$self_x, ny-$self_y, EASE_LINEAR);
}
sub card_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    card_arm_next_step();
}
sub card_move_rand() {
    var r: int = rand(65536)-32768;
    var a: int = r/3;
    if $self_x < -70fx {
        a = r/3;
    } else if $self_x > 70fx {
        a = r/3+32768;
        if a > 32768 { a = a-65536; }
    } else {
        a = r/4;
        var choose: int = rand(65536)%3;
        if $player_x > $self_x {
            if choose == 0 { a = a+32768; }
        } else {
            if choose != 0 { a = a+32768; }
        }
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    card_begin_angle(a as angle);
}
sub card_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        card_arm_next_step();
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    var until: int = $frame+SOURCE_LIMIT;
    var rank: int = global(GVAR_RANK);
    var c: int = 60;                 // diffI(60,60,60,70)
    if rank == 3 { c = 70; }
    var w: int = 120;                // !E/!N 120, !H 100, !LO 80
    if rank == 2 { w = 100; }
    if rank == 3 { w = 80; }
    set_self_int(0, 60);             // stationary until first source moveRand
    set_self_fx(0, 0fx);
    set_self_fx(1, 0fx);
    wait(90);                        // source Boss3 wait90
    // EffChargePoint3 here is a decorative charge effect.
    wait(80);                        // source Boss3 wait80
    var aoff: angle = 1820 as angle; // F0 = 0.174533rad (10deg)
    loop {
        if $frame >= until { return; }
        boss3_at(aoff, c);
        aoff = -aoff;
        card_wait(120);              // source fixed wait(120) before moveRand
        card_move_rand();
        card_wait(w);
    }
}

async sub boss_main() {
    set_invuln(65535);
    set_hitbox(24fx);                // source setHitbox(48,48), ordinary circle uses half
    set_hurtbox(20fx);               // source setHurtbox(40,40)
    phase_begin(0, pattern, TIME_LIMIT, 2600); // source slot0 HP2600 / 2100
    wait_spell();
    move_vel(0, 0deg, 0fx, EASE_LINEAR);
    loop { wait(1); }
}

// Training shell: the extra controller stays at (0,0) with body collision off.
// The real boss keeps source judgement and body hitbox.
async sub controller() {
    set_enemy_flag(ENEMY_NO_BODY, 1);
    set_invuln(65535);
    _ = spawn_enemy(0fx, 128fx, 19800, 0, 0, 0, boss_main);
    loop { wait(600); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1, 0, 0, 0, controller);
    loop { wait(600); }
}
